'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['applyCatalogCommand']);
const { applyCatalogCommand } = api;
assert.equal(typeof applyCatalogCommand, 'function');

const catalog = [
  { id: 2, name: 'Two', maker: 'B', released: 2000 },
  { id: 1, name: 'One', maker: 'A', released: 0 }
];
const before = JSON.stringify(catalog);
const all = applyCatalogCommand(catalog, { type: 'readAll' });
assert.deepEqual(all, { status: 200, data: catalog, catalog });
assert.equal(JSON.stringify(catalog), before);
assert.notStrictEqual(all.catalog, catalog);
assert.notStrictEqual(all.catalog[0], catalog[0]);
assert.notStrictEqual(all.data, all.catalog);
assert.notStrictEqual(all.data[0], all.catalog[0]);
all.data[0].name = 'changed';
assert.equal(all.catalog[0].name, 'Two');
assert.equal(catalog[0].name, 'Two');

const read = applyCatalogCommand(catalog, { type: 'read', id: 1 });
assert.deepEqual(read, { status: 200, data: catalog[1], catalog });
assert.notStrictEqual(read.data, read.catalog[1]);
assert.notStrictEqual(read.catalog[1], catalog[1]);
assert.deepEqual(applyCatalogCommand(catalog, { type: 'read', id: 99 }), {
  status: 404,
  data: { error: 'Item not found' },
  catalog
});

const newItem = { id: 3, name: 'Three', maker: 'C', released: 9999 };
const created = applyCatalogCommand(catalog, { type: 'create', item: newItem });
assert.deepEqual(created, { status: 201, data: newItem, catalog: [...catalog, newItem] });
assert.notStrictEqual(created.data, created.catalog[2]);
assert.notStrictEqual(created.catalog[2], newItem);
newItem.name = 'mutated input';
assert.equal(created.data.name, 'Three');
assert.equal(created.catalog[2].name, 'Three');

assert.deepEqual(applyCatalogCommand(catalog, {
  type: 'create', item: { id: 1, name: 'Duplicate', maker: 'D', released: 2020 }
}), {
  status: 409,
  data: { error: 'Duplicate id' },
  catalog
});

const replacement = { id: 2, name: 'Replacement', maker: 'R', released: 2026 };
const replaced = applyCatalogCommand(catalog, { type: 'replace', id: 2, item: replacement });
assert.deepEqual(replaced, {
  status: 200,
  data: replacement,
  catalog: [replacement, catalog[1]]
});
assert.notStrictEqual(replaced.data, replaced.catalog[0]);
assert.notStrictEqual(replaced.catalog[1], catalog[1]);

const removed = applyCatalogCommand(catalog, { type: 'remove', id: 2 });
assert.deepEqual(removed, { status: 200, data: catalog[0], catalog: [catalog[1]] });
assert.notStrictEqual(removed.data, catalog[0]);
assert.notStrictEqual(removed.catalog[0], catalog[1]);

for (const command of [
  null,
  {},
  { type: 'unknown' },
  { type: 'read', id: 0 },
  { type: 'create', item: { id: 4, name: '', maker: 'M', released: 1 } },
  { type: 'create', item: { id: 4, name: 'N', maker: 'M', released: 10000 } },
  { type: 'replace', id: 2, item: { id: 1, name: 'N', maker: 'M', released: 1 } },
  { type: 'remove', id: 1.5 }
]) {
  const result = applyCatalogCommand(catalog, command);
  assert.equal(result.status, 400);
  assert.deepEqual(result.data, { error: 'Invalid input' });
  assert.deepEqual(result.catalog, catalog);
  assert.notStrictEqual(result.catalog, catalog);
  assert.notStrictEqual(result.catalog[0], catalog[0]);
}

for (const malformed of [null, {}, [{ id: 0, name: 'N', maker: 'M', released: 1 }]]) {
  const result = applyCatalogCommand(malformed, { type: 'readAll' });
  assert.deepEqual(result, { status: 400, data: { error: 'Invalid input' }, catalog: [] });
}

assert.deepEqual(applyCatalogCommand([], { type: 'readAll' }), {
  status: 200, data: [], catalog: []
});

